package com.proben.api.service.shared;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.proben.api.dto.shared.SharedContextDTOs.CollectionTestResponse;
import com.proben.api.dto.shared.SharedContextDTOs.MappingTestResult;
import com.proben.api.dto.sensors.SensorIngestDTOs;
import com.proben.api.entity.sensors.MedicaoIngestaoSource;
import com.proben.api.service.sensors.SensorIngestOrchestrator;
import org.slf4j.Logger; import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.net.*; import java.net.http.*;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest;
import java.sql.Timestamp; import java.time.*; import java.util.*;

@Service
public class SharedContextCollector {
    private static final Logger log=LoggerFactory.getLogger(SharedContextCollector.class);
    private final JdbcTemplate jdbc; private final TransactionTemplate tx; private final ObjectMapper json;
    private final SensorIngestOrchestrator ingestion; private final CredentialEncryptionService credentials;
    private final boolean enabled; private final boolean allowLoopback;
    public SharedContextCollector(JdbcTemplate jdbc,TransactionTemplate tx,ObjectMapper json,SensorIngestOrchestrator ingestion, CredentialEncryptionService credentials,
            @Value("${proben.shared-context.collector.enabled:false}") boolean enabled,
            @Value("${proben.shared-context.collector.allow-loopback:false}") boolean allowLoopback){this.jdbc=jdbc;this.tx=tx;this.json=json;this.ingestion=ingestion;this.credentials=credentials;this.enabled=enabled;this.allowLoopback=allowLoopback;}

    @Scheduled(fixedDelayString="${proben.shared-context.collector.poll-interval:30s}")
    public void scheduled(){if(!enabled)return;for(int i=0;i<10;i++){Config c=claim(null);if(c==null)return;execute(c,true);}}
    public CollectionTestResponse collectNow(UUID id){Config c=claim(id);if(c==null)throw new IllegalStateException("integration is inactive or already running");return execute(c,true);}
    public CollectionTestResponse testNow(UUID id){Config c=claim(id);if(c==null)throw new IllegalStateException("integration is inactive or already running");return execute(c,false);}
    public CollectionTestResponse testConfiguration(UUID contextId, com.proben.api.dto.shared.SharedContextDTOs.IntegrationRequest r){
        if(r==null||r.sensorExternalId()==null||r.endpointUrl()==null)throw new IllegalArgumentException("sensor and endpoint are required");
        var locations=jdbc.query("""
          select case when c.location_mode='CAMPUS' then cp.latitude else c.latitude end latitude,
            case when c.location_mode='CAMPUS' then cp.longitude else c.longitude end longitude,c.location_mode,
            case when c.location_mode='CAMPUS' then cp.nome end campus
          from contexto_compartilhado c left join campus cp on cp.nome=c.campus_nome
          join sensor s on s.contexto_compartilhado_id=c.id and s.external_id=? where c.id=?
          """,(rs,n)->new Object[]{rs.getBigDecimal(1),rs.getBigDecimal(2),rs.getString(3),rs.getString(4)},r.sensorExternalId(),contextId);
        if(locations.isEmpty())throw new IllegalArgumentException("sensor must belong to context");Object[] location=locations.getFirst();
        var stored=jdbc.query("select id,credential_ciphertext,credential_iv from contexto_integracao_externa where sensor_external_id=?",(rs,n)->new StoredCredential(rs.getObject(1,UUID.class),rs.getBytes(2),rs.getBytes(3)),r.sensorExternalId()).stream().findFirst().orElse(null);
        UUID id=stored==null?UUID.randomUUID():stored.id;String auth=r.authMode()==null?"NONE":r.authMode().trim().toUpperCase();
        Config c=new Config(id,r.sensorExternalId(),r.endpointUrl(),r.metodo()==null?"GET":r.metodo().trim().toUpperCase(),r.requestBody(),auth,
          r.credentialHeader(),r.credentialQueryParam(),r.coordinateQueryParam(),r.queryParamsJson(),
          r.temperatureJsonPointer(),r.observedAtJsonPointer(),r.observedAtFormat()==null?"ISO_INSTANT":r.observedAtFormat().trim().toUpperCase(),r.sourceIdJsonPointer(),1,
          r.timeoutMillis()==null?5000:r.timeoutMillis(),1,(BigDecimal)location[0],(BigDecimal)location[1],(String)location[2],(String)location[3],null,
          stored==null?null:stored.ciphertext,stored==null?null:stored.iv,r.credential()==null||r.credential().isBlank()?null:r.credential(),
          r.contentType(),r.headersJson(),mappingJson(r),r.observedAtTimezone(),r.retryDelayMillis()==null?500:r.retryDelayMillis());
        Instant started=Instant.now();
        try{Parsed parsed=fetch(c);return previewResponse(parsed,started,false);}catch(Exception ex){return new CollectionTestResponse("TEST_FAILED",null,null,false,null,Duration.between(started,Instant.now()).toMillis(),c.method,sanitizedUrl(c.url),Map.of(),Map.of(),null,List.of(),null,c.observedFormat,classify(ex),safe(c,ex.getMessage()));}
    }

    private Config claim(UUID requested){return tx.execute(status->{String token=UUID.randomUUID().toString();String filter=requested==null?"i.ativo and i.automatic_collection and i.next_run_at<=now()":"i.id=?";Object[] args=requested==null?new Object[]{token}:new Object[]{requested,token};String sql="""
      with candidate as (select i.id from contexto_integracao_externa i where %s and (i.locked_until is null or i.locked_until<now()) order by i.next_run_at for update of i skip locked limit 1)
      update contexto_integracao_externa i set locked_until=now()+interval '2 minutes',locked_by=?,last_started_at=now(),last_error=null
      from candidate where i.id=candidate.id returning i.*,
        (select c.location_mode from contexto_compartilhado c where c.id=i.contexto_id) location_mode,
        (select case when c.location_mode='CAMPUS' then cp.nome else null end from contexto_compartilhado c left join campus cp on cp.nome=c.campus_nome where c.id=i.contexto_id) campus_used,
        (select case when c.location_mode='CAMPUS' then cp.latitude else c.latitude end from contexto_compartilhado c left join campus cp on cp.nome=c.campus_nome where c.id=i.contexto_id) resolved_latitude,
        (select case when c.location_mode='CAMPUS' then cp.longitude else c.longitude end from contexto_compartilhado c left join campus cp on cp.nome=c.campus_nome where c.id=i.contexto_id) resolved_longitude
      """.formatted(filter);return jdbc.query(sql,(rs,n)->new Config(rs.getObject("id",UUID.class),rs.getString("sensor_external_id"),rs.getString("endpoint_url"),rs.getString("metodo"),rs.getString("request_body"),rs.getString("auth_mode"),rs.getString("credential_header"),rs.getString("credential_query_param"),rs.getString("coordinate_query_param"),rs.getString("query_params_json"),rs.getString("temperature_json_pointer"),rs.getString("observed_at_json_pointer"),rs.getString("observed_at_format"),rs.getString("source_id_json_pointer"),rs.getInt("interval_seconds"),rs.getInt("timeout_millis"),rs.getInt("max_attempts"),rs.getBigDecimal("resolved_latitude"),rs.getBigDecimal("resolved_longitude"),rs.getString("location_mode"),rs.getString("campus_used"),token,rs.getBytes("credential_ciphertext"),rs.getBytes("credential_iv"),null,rs.getString("content_type"),rs.getString("headers_json"),rs.getString("mappings_json"),rs.getString("timestamp_timezone"),rs.getInt("retry_delay_millis")),args).stream().findFirst().orElse(null);});}

    private CollectionTestResponse execute(Config c,boolean persist){Instant started=Instant.now();Exception last=null;for(int attempt=1;attempt<=c.maxAttempts;attempt++)try{Parsed p=fetch(c);if(p.errorMessage!=null)throw new IllegalArgumentException(p.errorMessage);requireOwnership(c);if(!persist){audit(c,started,"TEST_SUCCESS",p.observed,null,null);release(c,"TEST_SUCCESS",p.observed,null);return previewResponse(p,started,false);}String identity=(p.sourceId==null?c.id.toString():p.sourceId)+"|"+locationHash(c)+"|"+p.observed;String messageId="external:"+hex(identity).substring(0,32);var outcome=ingestion.ingest("shared-context-collector",new SensorIngestDTOs.CanonicalIngestRequest(messageId,c.sensor,p.observed,MedicaoIngestaoSource.API,Instant.now(),p.values));if(outcome.status().isError())throw new IllegalStateException("canonical ingestion conflict");requireOwnership(c);String result=outcome.response().duplicate()?"REPEATED_OBSERVATION":"NEW_MEASUREMENT";audit(c,started,result,p.observed,outcome.response().medicaoId(),null);release(c,result,p.observed,null);return new CollectionTestResponse(result,p.observed,firstNumeric(p.values),true);}catch(Exception ex){last=ex;if(!owns(c))throw new IllegalStateException("collection lease lost");if(attempt<c.maxAttempts)try{Thread.sleep(Math.min((long)c.retryDelayMillis*attempt,60000L));}catch(InterruptedException x){Thread.currentThread().interrupt();last=x;break;}}String error=safe(c,last==null?null:last.getMessage());if(owns(c)){audit(c,started,"FAILED",null,null,error);release(c,"FAILED",null,error);}log.warn("application=proben-api event=shared_context_collection_failed integrationId={} error={}",c.id,error);throw new IllegalStateException(error);}

    private Parsed fetch(Config c)throws Exception {if(c.latitude==null||c.longitude==null)throw new IllegalStateException("configured geographic reference has no coordinates");Instant execution=Instant.now();Map<String,String> query=new LinkedHashMap<>();if(c.queryJson!=null){JsonNode q=json.readTree(c.queryJson);if(!q.isObject())throw new IllegalArgumentException("queryParamsJson must be a JSON object");q.properties().forEach(e->query.put(e.getKey(),template(e.getValue().asText(),c,execution)));}if(c.coordinateParam!=null&&!query.containsKey(c.coordinateParam))query.put(c.coordinateParam,c.latitude.toPlainString()+","+c.longitude.toPlainString());String secret=secret(c);if("QUERY".equals(c.authMode))query.put(c.credentialQueryParam,secret);URI uri=uri(c.url,query);validateTarget(uri,allowLoopback);Map<String,String> requestHeaders=headers(c,execution);HttpRequest.Builder b=HttpRequest.newBuilder(uri).timeout(Duration.ofMillis(c.timeoutMillis));requestHeaders.forEach(b::header);if("HEADER".equals(c.authMode))b.header(c.credentialHeader,secret);if("BEARER".equals(c.authMode))b.header("Authorization","Bearer "+secret);if("POST".equals(c.method))b.header("Content-Type",c.contentType==null?"application/json":c.contentType).POST(HttpRequest.BodyPublishers.ofString(template(c.body==null?"{}":c.body,c,execution)));else b.GET();long requestStarted=System.nanoTime();HttpResponse<String> response=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(c.timeoutMillis)).followRedirects(HttpClient.Redirect.NEVER).build().send(b.build(),HttpResponse.BodyHandlers.ofString());long durationMillis=(System.nanoTime()-requestStarted)/1_000_000L;if(response.body()!=null&&response.body().length()>1_048_576)throw new IllegalStateException("provider response exceeds size limit");if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("provider HTTP status "+response.statusCode());JsonNode root;try{root=json.readTree(response.body());}catch(Exception ex){throw new IllegalArgumentException("provider returned invalid JSON");}MapResult mapped=mapValues(c,root);Instant observed=null;String observedOriginal=c.observedPointer==null?null:text(root.at(c.observedPointer));String errorType=mapped.errorType,errorMessage=mapped.errorMessage;try{observed=parseObserved(c,root,execution);}catch(RuntimeException ex){errorType="TIMESTAMP_ERROR";errorMessage=ex.getMessage();}Map<String,String> safeQuery=new LinkedHashMap<>(query);if("QUERY".equals(c.authMode))safeQuery.put(c.credentialQueryParam,"[REDACTED]");Map<String,String> safeHeaders=new LinkedHashMap<>(requestHeaders);if("HEADER".equals(c.authMode))safeHeaders.put(c.credentialHeader,"[REDACTED]");if("BEARER".equals(c.authMode))safeHeaders.put("Authorization","Bearer [REDACTED]");return new Parsed(mapped.values,observed,c.sourceIdPointer==null?null:text(root.at(c.sourceIdPointer)),response.statusCode(),durationMillis,c.method,sanitizedUrl(c.url),safeHeaders,safeQuery,previewJson(root,secret),mapped.previews,observedOriginal,c.observedFormat,errorType,errorMessage);}
    private String secret(Config c){if("NONE".equals(c.authMode))return null;if(c.ephemeralSecret!=null){if(c.ephemeralSecret.isBlank())throw new IllegalArgumentException("credential must not be blank");return c.ephemeralSecret;}if(c.credentialCiphertext!=null)return credentials.decrypt(c.id,c.credentialCiphertext,c.credentialIv);throw new IllegalStateException("configured credential is absent");}
    private void audit(Config c,Instant started,String outcome,Instant observed,UUID measurement,String error){jdbc.update("insert into contexto_coleta_execucao(id,integracao_id,started_at,finished_at,outcome,observation_at,medicao_id,latitude,longitude,location_source,campus_nome,location_hash,error_message) values (?,?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),c.id,Timestamp.from(started),Timestamp.from(Instant.now()),outcome,observed==null?null:Timestamp.from(observed),measurement,c.latitude,c.longitude,c.locationMode,c.campus,locationHash(c),error);}
    private boolean owns(Config c){return Boolean.TRUE.equals(jdbc.queryForObject("select count(*)=1 from contexto_integracao_externa where id=? and locked_by=? and locked_until>now()",Boolean.class,c.id,c.lockToken));}
    private void requireOwnership(Config c){if(!owns(c))throw new IllegalStateException("collection lease lost");}
    private void release(Config c,String outcome,Instant observed,String error){jdbc.update("update contexto_integracao_externa set last_success_at=case when ?<>'FAILED' then now() else last_success_at end,next_run_at=now()+(interval '1 second'*interval_seconds),locked_until=null,locked_by=null,last_outcome=?,last_observation_at=coalesce(?,last_observation_at),last_error=? where id=? and locked_by=?",outcome,outcome,observed==null?null:Timestamp.from(observed),error,c.id,c.lockToken);}
    private static URI uri(String base,Map<String,String> params){StringBuilder value=new StringBuilder(base);char separator=base.contains("?")?'&':'?';for(var e:params.entrySet()){value.append(separator).append(URLEncoder.encode(e.getKey(),StandardCharsets.UTF_8)).append('=').append(URLEncoder.encode(e.getValue(),StandardCharsets.UTF_8));separator='&';}return URI.create(value.toString());}
    static void validateTarget(URI uri,boolean allowLoopback)throws UnknownHostException {if(!Set.of("http","https").contains(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getFragment()!=null)throw new IllegalArgumentException("provider URL is not an allowed HTTP target");for(InetAddress address:InetAddress.getAllByName(uri.getHost())){boolean local=address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress()||address.isSiteLocalAddress()||address.isMulticastAddress();if(local&&!(allowLoopback&&address.isLoopbackAddress()))throw new IllegalArgumentException("provider URL resolves to a non-public address");}}
    private static Instant epoch(JsonNode n){if(!n.canConvertToLong())throw new IllegalArgumentException("provider observation time is invalid");return Instant.ofEpochSecond(n.longValue());}
    private static String locationHash(Config c){try{return hex(c.latitude.toPlainString()+"|"+c.longitude.toPlainString());}catch(Exception e){throw new IllegalStateException(e);}}private String safe(Config c,String v){String sanitized=v==null?"collection failed":v;String resolved=null;try{resolved=secret(c);}catch(RuntimeException ignored){}if(resolved!=null&&!resolved.isBlank())sanitized=sanitized.replace(resolved,"[REDACTED]");return sanitized.substring(0,Math.min(sanitized.length(),900));}private static String text(JsonNode n){return n==null||n.isMissingNode()||n.isNull()?null:n.asText();}private static String hex(String v)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}
    private String mappingJson(com.proben.api.dto.shared.SharedContextDTOs.IntegrationRequest r){try{return json.writeValueAsString(r.mappings()==null?List.of():r.mappings());}catch(Exception ex){throw new IllegalArgumentException("mappings are invalid");}}
    private Map<String,String> headers(Config c,Instant execution)throws Exception{Map<String,String> result=new LinkedHashMap<>();if(c.headersJson==null)return result;JsonNode rows=json.readTree(c.headersJson);if(!rows.isArray())throw new IllegalArgumentException("headersJson must be an array");for(JsonNode row:rows){String key=row.path("key").asText();if(Set.of("host","content-length","connection","transfer-encoding").contains(key.toLowerCase()))throw new IllegalArgumentException("forbidden HTTP header");result.put(key,template(row.path("value").asText(),c,execution));}return result;}
    private static String template(String value,Config c,Instant execution){if(value==null)return null;String result=value.replace("{{context.latitude}}",c.latitude.toPlainString()).replace("{{context.longitude}}",c.longitude.toPlainString()).replace("{{context.coordinates}}",c.latitude.toPlainString()+","+c.longitude.toPlainString()).replace("{{execution.timestamp}}",execution.toString());if(result.contains("{{"))throw new IllegalArgumentException("template contains an unsupported variable");return result;}
    private MapResult mapValues(Config c,JsonNode root)throws Exception{Map<String,Object> result=new LinkedHashMap<>();List<MappingTestResult> previews=new ArrayList<>();String firstType=null,firstError=null;JsonNode rows=c.mappingsJson==null?json.createArrayNode():json.readTree(c.mappingsJson);if(!rows.isArray())throw new IllegalArgumentException("mappingsJson must be an array");for(JsonNode row:rows){UUID parameterId=null;try{String rawId=row.path("parametroDefId").asText();if(!rawId.isBlank())parameterId=UUID.fromString(rawId);}catch(RuntimeException ignored){}String name=row.path("parameterName").asText();String pointer=row.path("jsonPointer").asText();boolean required=row.path("required").asBoolean(true);String unit=row.path("targetUnit").asText(row.path("sourceUnit").asText());JsonNode value=root.at(pointer);String found=value.isMissingNode()?null:limited(value.toString(),500);String detected=detectedType(value);try{if(value.isMissingNode()||value.isNull()){if(required)throw new IllegalArgumentException("required JSON Pointer is absent: "+pointer);previews.add(new MappingTestResult(parameterId,name,pointer,found,detected,null,unit,true,null));continue;}String type=row.path("expectedType").asText("NUMERIC");Object converted;switch(type){case "NUMERIC"->{if(!value.isNumber())throw new IllegalArgumentException("JSON Pointer is not numeric: "+pointer);converted=convert(value.decimalValue(),row.path("conversion").asText("NONE"));}case "BOOLEAN"->{if(!value.isBoolean())throw new IllegalArgumentException("JSON Pointer is not boolean: "+pointer);converted=value.booleanValue();}case "TEXT"->converted=value.isTextual()?value.textValue():value.asText();default->throw new IllegalArgumentException("unsupported mapping type: "+type);}if(name==null||name.isBlank())throw new IllegalArgumentException("mapping parameterName is required");result.put(name,converted);previews.add(new MappingTestResult(parameterId,name,pointer,found,detected,String.valueOf(converted),unit,true,null));}catch(RuntimeException ex){previews.add(new MappingTestResult(parameterId,name,pointer,found,detected,null,unit,false,ex.getMessage()));if(firstError==null){firstType=value.isMissingNode()?"POINTER_ERROR":"CONVERSION_ERROR";firstError=ex.getMessage();}}}if(result.isEmpty()&&rows.isEmpty()&&c.temperaturePointer!=null){JsonNode value=root.at(c.temperaturePointer);if(value.isNumber()){result.put("temperatura_externa",value.decimalValue());previews.add(new MappingTestResult(null,"temperatura_externa",c.temperaturePointer,limited(value.toString(),500),detectedType(value),value.decimalValue().toPlainString(),"",true,null));}else{firstType="POINTER_ERROR";firstError="provider temperature is absent or non-numeric";previews.add(new MappingTestResult(null,"temperatura_externa",c.temperaturePointer,null,detectedType(value),null,"",false,firstError));}}if(result.isEmpty()&&firstError==null){firstType="MAPPING_ERROR";firstError="response produced no mapped parameters";}return new MapResult(result,previews,firstType,firstError);}
    private static BigDecimal convert(BigDecimal value,String conversion){return switch(conversion==null?"NONE":conversion){case "NONE"->value;case "C_TO_F"->value.multiply(BigDecimal.valueOf(9)).divide(BigDecimal.valueOf(5),6,java.math.RoundingMode.HALF_UP).add(BigDecimal.valueOf(32));case "F_TO_C"->value.subtract(BigDecimal.valueOf(32)).multiply(BigDecimal.valueOf(5)).divide(BigDecimal.valueOf(9),6,java.math.RoundingMode.HALF_UP);default->throw new IllegalArgumentException("unsupported conversion: "+conversion);};}
    private static BigDecimal firstNumeric(Map<String,Object> values){return values.values().stream().filter(BigDecimal.class::isInstance).map(BigDecimal.class::cast).findFirst().orElse(null);}
    private CollectionTestResponse previewResponse(Parsed p,Instant started,boolean persisted){String outcome=p.errorMessage==null?"TEST_SUCCESS":"TEST_FAILED";return new CollectionTestResponse(outcome,p.observed,firstNumeric(p.values),persisted,p.httpStatus,p.durationMillis==null?Duration.between(started,Instant.now()).toMillis():p.durationMillis,p.method,p.sanitizedUrl,p.headers,p.queryParameters,p.rawJson,p.mappings,p.observedAtOriginal,p.observedAtFormat,p.errorType,p.errorMessage);}
    private String previewJson(JsonNode root,String secret){try{String value=json.writerWithDefaultPrettyPrinter().writeValueAsString(root);if(secret!=null&&!secret.isBlank())value=value.replace(secret,"[REDACTED]");return limited(value,16_384);}catch(Exception ex){return "";}}
    private static String sanitizedUrl(String value){try{URI uri=URI.create(value);return new URI(uri.getScheme(),null,uri.getHost(),uri.getPort(),uri.getPath(),null,null).toString();}catch(Exception ex){return "invalid endpoint";}}
    private static String detectedType(JsonNode value){if(value==null||value.isMissingNode())return "MISSING";if(value.isNull())return "NULL";if(value.isNumber())return "NUMERIC";if(value.isBoolean())return "BOOLEAN";if(value.isTextual())return "TEXT";if(value.isArray())return "ARRAY";if(value.isObject())return "OBJECT";return "UNKNOWN";}
    private static String limited(String value,int max){if(value==null)return null;return value.substring(0,Math.min(value.length(),max));}
    private static String classify(Exception ex){String message=ex.getMessage()==null?"":ex.getMessage().toLowerCase();if(ex instanceof HttpTimeoutException||message.contains("timed out"))return "TIMEOUT";if(message.contains("http status 401")||message.contains("http status 403"))return "AUTHENTICATION_REJECTED";if(message.contains("http status"))return "HTTP_ERROR";if(message.contains("invalid json"))return "INVALID_JSON";if(message.contains("pointer"))return "POINTER_ERROR";if(message.contains("conversion")||message.contains("numeric")||message.contains("boolean"))return "CONVERSION_ERROR";if(ex instanceof ConnectException||ex instanceof UnknownHostException)return "CONNECTION_ERROR";return "CONFIGURATION_ERROR";}
    private static Instant parseObserved(Config c,JsonNode root,Instant collection){String format=c.observedFormat==null?"ISO_8601":c.observedFormat;if("COLLECTION_TIME".equals(format))return collection;JsonNode value=root.at(c.observedPointer);return switch(format){case "UNIX_SECONDS"->epoch(value);case "UNIX_MILLISECONDS"->{if(!value.canConvertToLong())throw new IllegalArgumentException("provider observation time is invalid");yield Instant.ofEpochMilli(value.longValue());}case "ISO_INSTANT","ISO_8601"->{if(!value.isTextual())throw new IllegalArgumentException("provider observation time is absent");try{yield OffsetDateTime.parse(value.asText()).toInstant();}catch(RuntimeException first){try{yield LocalDateTime.parse(value.asText()).atZone(ZoneId.of(c.observedTimezone==null?"UTC":c.observedTimezone)).toInstant();}catch(RuntimeException second){throw new IllegalArgumentException("provider observation time is invalid");}}}default->throw new IllegalArgumentException("unsupported observation time format");};}
    private record MapResult(Map<String,Object> values,List<MappingTestResult> previews,String errorType,String errorMessage){}
    private record Parsed(Map<String,Object> values,Instant observed,String sourceId,Integer httpStatus,Long durationMillis,
                          String method,String sanitizedUrl,Map<String,String> headers,Map<String,String> queryParameters,
                          String rawJson,List<MappingTestResult> mappings,String observedAtOriginal,String observedAtFormat,
                          String errorType,String errorMessage){}
    private record Config(UUID id,String sensor,String url,String method,String body,String authMode,String credentialHeader,String credentialQueryParam,String coordinateParam,String queryJson,String temperaturePointer,String observedPointer,String observedFormat,String sourceIdPointer,int intervalSeconds,int timeoutMillis,int maxAttempts,BigDecimal latitude,BigDecimal longitude,String locationMode,String campus,String lockToken,byte[] credentialCiphertext,byte[] credentialIv,String ephemeralSecret,String contentType,String headersJson,String mappingsJson,String observedTimezone,int retryDelayMillis){}
    private record StoredCredential(UUID id,byte[] ciphertext,byte[] iv){}
}
